# Resolves the runtime .app generated by Convert-BcAppsToRuntimePackages.
# From BC29, Get-NavAppRuntimePackage writes the container path to the pipeline, so BcContainerHelper
# reports runtimeFile as "<dest>\C:\dest\<file>\<file>" (or an array) instead of "<dest>\<file>".
# The file name is always the last segment, and the file is always written to the destination folder.
function ResolveRuntimeAppFile {
    Param(
        [string] $destinationFolder,
        [object] $runtimeFile
    )
    $reported = @($runtimeFile | Where-Object { $_ } | ForEach-Object { "$_" })
    if ($reported.Count -eq 0) { throw "Could not generate runtime package" }
    $fileName = [System.IO.Path]::GetFileName($reported[-1])
    $resolved = Join-Path $destinationFolder $fileName
    if (-not (Test-Path -LiteralPath $resolved -PathType Leaf)) {
        throw "Could not generate runtime package (expected $resolved, BcContainerHelper reported '$($reported -join ', ')')"
    }
    return $resolved
}
